/**
 * ⏱️SIGKILLs `pid`'s whole process tree, not just `pid` — a timed-out `spawnSync`/`execFileSync` only signals the
 * direct child, leaking forked worker pools (e.g. vitest's `workers/forks.js`) that keep burning CPU indefinitely.
 * Requires the child to have been spawned with `detached: true` on POSIX so `pid` is its own process-group leader.
 */
function killBudgetTree(pid: number): void {
  terminateOwnedProcessTree(pid);
}

/** 🎭️ Playwright is TEST-ONLY and loaded lazily. The specifier is indirected so no bundler can
 * statically resolve it: this module is reachable from `⚙️vite.config.ts`, and a literal
 * `import("playwright")` makes bun follow it into a browser build, failing on the uninstalled
 * optional `chromium-bidi`. Runtime behaviour is identical. */

/** 🦀️ Composes repository Cargo preparation with neutral bounded test execution. */
export async function runRepositoryTestCommand(command: string, args: string[], options: { cwd?: string; env?: Readonly<Record<string, string | undefined>>; budgetMs?: number; onTimeoutHint?: string; throwOnFailure?: boolean } = {}): Promise<void> {
  const cwd = options.cwd ?? process.cwd();
  if (command === "cargo") prepareCargoWorkspaceInvocation(getWorkspaceRoot(), args, cwd);
  await runBudgetedTestCommand(command, args, { ...options, cwd, budgetMs: options.budgetMs ?? testLevelBudgetMs() });
}

/** 📦️Runs a build-budgeted command while capturing metadata and replaying diagnostics only on failure. */
export function capturedTestFailureDiagnostics(stdout: string, stderr: string): string {
  const rendered: string[] = [];
  for (const line of stdout.split(/\r?\n/)) {
    try {
      const message = JSON.parse(line) as { reason?: string; message?: { level?: string; message?: string; rendered?: string; spans?: { file_name?: string; line_start?: number; column_start?: number; is_primary?: boolean }[] } };
      if (message.reason === "compiler-message" && message.message?.level === "error") {
        const span = message.message.spans?.find((candidate) => candidate.is_primary) ?? message.message.spans?.[0];
        const location = span?.file_name ? `\n  --> ${span.file_name}:${span.line_start ?? 0}:${span.column_start ?? 0}` : "";
        rendered.push(message.message.rendered ?? `${message.message.message ?? "Cargo compiler error"}${location}`);
      }
    } catch {}
  }
  const stderrStart = stderr.search(/^(?:error(?:\[[A-Z]\d+\])?:|Caused by:)/m);
  if (rendered.length === 0 && stderrStart >= 0) return stderr.slice(stderrStart).trimEnd();
  const stderrErrors = stderr.split(/\r?\n/).filter((line) => /^(?:error(?:\[[A-Z]\d+\])?:|Caused by:)/.test(line));
  const diagnostics = [...rendered, ...stderrErrors];
  return diagnostics.length > 0 ? diagnostics.join("\n") : `${stdout.slice(-16 * 1024)}${stderr.slice(-16 * 1024)}`;
}

//#region 🦀️CargoPackageResolver
interface CrateIndexRecord {
  dir: string;
  pkgName: string;
  libName: string;
}


const CARGO_PREFIX_WORDS = new Set(["semio", "s", "framework", "os", "kernel", "plugin", "module", "tech", "app"]);

function generateCargoVariants(name: string): string[] {
  const variants = new Set<string>([name]);
  const parts = name.split("-");

  let firstNonPrefix = parts.length - 1;
  for (let i = 0; i < parts.length; i++) {
    if (!CARGO_PREFIX_WORDS.has(parts[i])) {
      firstNonPrefix = i;
      break;
    }
  }

  const coreSuffix = parts.slice(firstNonPrefix).join("-");
  variants.add(coreSuffix);

  const prefixParts = parts.slice(0, firstNonPrefix);
  for (let i = 0; i < prefixParts.length; i++) {
    variants.add(parts.slice(i).join("-"));
    variants.add([prefixParts[i], ...parts.slice(firstNonPrefix)].join("-"));
  }

  return Array.from(variants);
}

/** 🦀️ Indexes present package identities across explicitly authored Cargo workspace owners. */
function getCargoWorkspaceIndex(repoRoot = getWorkspaceRoot()) {
  const exactPkgNames = new Set<string>();
  const libNameToCrates = new Map<string, CrateIndexRecord[]>();
  const aliasToCrates = new Map<string, CrateIndexRecord[]>();

  const addAlias = (alias: string, record: CrateIndexRecord) => {
    if (!alias) return;
    const normalized = alias.replaceAll("-", "_").toLowerCase();
    const list = aliasToCrates.get(normalized) ?? [];
    if (!list.includes(record)) list.push(record);
    aliasToCrates.set(normalized, list);
  };

  for (const member of cargoRepositoryPackages(repoRoot)) {
    const manifest = join(repoRoot, member.manifest);
    const parsed = Bun.TOML.parse(readFileSync(manifest, "utf8")) as { package?: { name?: string }; lib?: { name?: string } };
    const pkgName = member.name;
    const libName = parsed.lib?.name ?? pkgName.replaceAll("-", "_");
    const record: CrateIndexRecord = { dir: dirname(manifest), pkgName, libName };
    exactPkgNames.add(pkgName);
    libNameToCrates.set(libName, [...(libNameToCrates.get(libName) ?? []), record]);
    addAlias(libName, record);
    addAlias(pkgName, record);
    for (const variant of generateCargoVariants(pkgName)) addAlias(variant, record);
    for (const variant of generateCargoVariants(libName.replaceAll("_", "-"))) addAlias(variant, record);
  }
  return { exactPkgNames, libNameToCrates, aliasToCrates };
}

export function resolveCargoPackageName(pkg: string, cwd: string): string {
  const index = getCargoWorkspaceIndex();
  if (index.exactPkgNames.has(pkg)) return pkg;

  // 1. Check local Cargo.toml in cwd, cwd/rs, dirname(cwd)
  for (const candidateDir of [cwd, join(cwd, "rs"), dirname(cwd)]) {
    const cargoPath = join(candidateDir, "Cargo.toml");
    if (existsSync(cargoPath)) {
      try {
        const content = readFileSync(cargoPath, "utf8");
        const pkgMatch = content.match(/\[package\][\s\S]*?\bname\s*=\s*"([^"]+)"/);
        const libMatch = content.match(/\[lib\][\s\S]*?\bname\s*=\s*"([^"]+)"/);
        const localPkg = pkgMatch ? pkgMatch[1] : null;
        const localLib = libMatch ? libMatch[1] : localPkg ? localPkg.replaceAll("-", "_") : null;
        if (localPkg) {
          if (pkg === localLib || pkg === localPkg || pkg.replaceAll("-", "_") === localLib || pkg.replaceAll("_", "-") === localPkg) {
            return localPkg;
          }
        }
      } catch {
        /* ignore */
      }
    }
  }

  // 2. Direct libName lookup
  const byLib = index.libNameToCrates.get(pkg);
  if (byLib && byLib.length > 0) {
    if (byLib.length === 1) return byLib[0].pkgName;
    let best = byLib[0];
    let bestDist = Infinity;
    for (const item of byLib) {
      const dist = relative(cwd, item.dir).length;
      if (dist < bestDist) {
        bestDist = dist;
        best = item;
      }
    }
    return best.pkgName;
  }

  // 3. Alias / prefix-variant lookup
  const normPkg = pkg.replaceAll("-", "_").toLowerCase();
  const byAlias = index.aliasToCrates.get(normPkg);
  if (byAlias && byAlias.length > 0) {
    if (byAlias.length === 1) return byAlias[0].pkgName;
    let best = byAlias[0];
    let bestDist = Infinity;
    for (const item of byAlias) {
      const dist = relative(cwd, item.dir).length;
      if (dist < bestDist) {
        bestDist = dist;
        best = item;
      }
    }
    return best.pkgName;
  }

  // 4. Fallback if cwd has Cargo.toml
  for (const candidateDir of [cwd, join(cwd, "rs")]) {
    const cargoPath = join(candidateDir, "Cargo.toml");
    if (existsSync(cargoPath)) {
      try {
        const content = readFileSync(cargoPath, "utf8");
        const pkgMatch = content.match(/\[package\][\s\S]*?\bname\s*=\s*"([^"]+)"/);
        if (pkgMatch) return pkgMatch[1];
      } catch {
        /* ignore */
      }
    }
  }

  return pkg;
}

export function resolveCargoPackageNames(packages: string[], cwd: string): string[] {
  if (packages.length === 0) {
    for (const candidateDir of [cwd, join(cwd, "rs")]) {
      const cargoPath = join(candidateDir, "Cargo.toml");
      if (existsSync(cargoPath)) {
        try {
          const content = readFileSync(cargoPath, "utf8");
          const pkgMatch = content.match(/\[package\][\s\S]*?\bname\s*=\s*"([^"]+)"/);
          if (pkgMatch) return [pkgMatch[1]];
        } catch {
          /* ignore */
        }
      }
    }
    return [];
  }
  return packages.map((pkg) => resolveCargoPackageName(pkg, cwd));
}
