export function repositoryCargoTestPolicyV1(manifestPath:string,cwd:string,env:Readonly<Record<string,string|undefined>>=process.env):CargoTestPolicyV1 {
  const repository=getWorkspaceRoot(), path=resolve(repository,manifestPath), relativePath=relative(repository,path).split(sep).join("/"), scope=cargoWorkspaceForManifest(repository,relativePath), cargo=Bun.TOML.parse(readFileSync(path,"utf8")) as {package?:{name?:string}};
  if(!cargo.package?.name)throw Error(`Cargo test policy requires a package manifest: ${manifestPath}`);
  const level=isTestLevel(env.SEMIO_TEST_LEVEL)?env.SEMIO_TEST_LEVEL:activeTestLevel(), configPath=join(repository,scope.directory,".config","nextest.toml"), artifact=nextestArtifactLocation(cwd,env);
  if(!existsSync(configPath))throw Error(`Selected Cargo test configuration is missing: ${configPath}`);
  return {version:1,manifestPath:path,targetDirectory:cargoTargetDirectory(repository,env),nextest:cargoNextestAvailable(),configPath,level,assertionBudgets:Object.fromEntries(TEST_LEVELS.map(value=>[value,packageTestBudgetMs([cargo.package!.name!],value,env)])) as Record<TestLevel,number>,buildBudgetMs:buildBudgetMs(env),assertionThreads:Math.max(1,availableParallelism()-Math.max(1,Math.ceil(availableParallelism()/4))),artifactDirectory:artifact.directory,retainArtifacts:artifact.retain,coverageEnabled:env.SEMIO_COVERAGE==="1",coveragePath:join(coverageDir(repository,"rust"),`${coverageSlug(cargo.package.name)}.lcov`),rustMinStack:env.RUST_MIN_STACK??"134217728"};
}

/** 🦀️ Composes selected repository workspace preparation with explicit neutral Cargo execution. */
export async function runRepositoryCargoTests(packages:string[],cwd:string,extraArgs:string[]=[],env:Readonly<Record<string,string|undefined>>=process.env):Promise<void>{
  const repository=getWorkspaceRoot(), rows=packages.map(name=>cargoRepositoryPackage(repository,name));
  const manifests=rows.length?[...new Set(rows.map(row=>row.manifest))]:[relative(repository,join(cwd,"Cargo.toml"))];
  const scopes=new Map<string,string[]>();
  for(const manifest of manifests){const scope=cargoWorkspaceForManifest(repository,manifest).directory;scopes.set(scope,[...(scopes.get(scope)??[]),manifest]);}
  for(const manifests of scopes.values()){
    const manifest=resolve(repository,manifests[0]!),names=rows.filter(row=>manifests.includes(row.manifest)).map(row=>row.name);
    prepareCargoWorkspaceInvocation(repository,["test","--manifest-path",manifest],cwd);
    const policy=repositoryCargoTestPolicyV1(manifest,cwd,env);
    await runCargoTestsV1({manifestPath:manifest,packages:names,cwd,extraArgs,environment:env},{...policy,assertionBudgets:names.length?Object.fromEntries(TEST_LEVELS.map(value=>[value,packageTestBudgetMs(names,value,env)])) as Record<TestLevel,number>:policy.assertionBudgets});
  }
}

function cargoNextestAvailable(): boolean {
  const result = spawnSync("cargo", ["nextest", "--version"], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
  return result.status === 0;
}

export interface RunProbeResult {
  status: number | null;
  stdout: string;
  stderr: string;
  signal: NodeJS.Signals | null;
}

type CapturedSpawnOptions = Readonly<{
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  input?: Buffer | string;
  timeout?: number;
  killSignal?: NodeJS.Signals | number;
}>;

type CapturedSpawnResult = Readonly<{
  status: number | null;
  stdout: Buffer;
  stderr: Buffer;
  signal: NodeJS.Signals | null;
  error?: Error;
}>;

const CAPTURE_WRAPPER_SOURCE = `
const { readFileSync, writeFileSync } = await import("node:fs");
const { spawnSync } = await import("node:child_process");
const spec = JSON.parse(readFileSync(process.env.SEMIO_PROCESS_CAPTURE_SPEC, "utf8"));
const input = spec.input === undefined ? undefined : Buffer.from(spec.input, "base64");
const result = spawnSync(spec.cmd, spec.args, { cwd: spec.cwd, env: spec.env, timeout: spec.timeout, killSignal: spec.killSignal, stdio: [input === undefined ? "ignore" : "pipe", "pipe", "pipe"], ...(input === undefined ? {} : { input }), maxBuffer: 536870912 });
writeFileSync(spec.stdoutPath, result.stdout ?? Buffer.alloc(0));
writeFileSync(spec.stderrPath, result.stderr ?? Buffer.alloc(0));
const sourceError = result.error;
const error = sourceError ? { message: sourceError.message, code: sourceError.code, errno: sourceError.errno, syscall: sourceError.syscall, path: sourceError.path, spawnargs: sourceError.spawnargs } : undefined;
writeFileSync(spec.metaPath, JSON.stringify({ status: result.status, signal: result.signal, error }));
`;

/** 📥️Captures subprocess bytes through a child-owned OS-file bridge so Bun test and native process hosts agree exactly. */
function spawnCapturedSync(cmd: string, args: readonly string[], opts: CapturedSpawnOptions = {}): CapturedSpawnResult {
  const captureRoot = mkdtempSync(join(tmpdir(), "semio-process-capture-"));
  const stdoutPath = join(captureRoot, "stdout");
  const stderrPath = join(captureRoot, "stderr");
  const metaPath = join(captureRoot, "meta.json");
  const specPath = join(captureRoot, "spec.json");
  const env = Object.fromEntries(Object.entries(opts.env ?? process.env).filter((entry): entry is [string, string] => entry[1] !== undefined));
  writeFileSync(
    specPath,
    JSON.stringify({ cmd, args, cwd: opts.cwd, env, input: opts.input === undefined ? undefined : Buffer.from(opts.input).toString("base64"), timeout: opts.timeout, killSignal: opts.killSignal, stdoutPath, stderrPath, metaPath }),
  );
  try {
    const launcher = spawnSync(process.execPath, ["-e", CAPTURE_WRAPPER_SOURCE], {
      env: { ...process.env, SEMIO_PROCESS_CAPTURE_SPEC: specPath },
      timeout: opts.timeout ? opts.timeout + 5_000 : undefined,
      killSignal: opts.killSignal,
      stdio: "ignore",
    });
    if (!existsSync(metaPath)) return { status: launcher.status, stdout: Buffer.alloc(0), stderr: Buffer.alloc(0), signal: launcher.signal, error: launcher.error };
    const meta = JSON.parse(readFileSync(metaPath, "utf8")) as { status: number | null; signal: NodeJS.Signals | null; error?: NodeJS.ErrnoException };
    const error = meta.error ? Object.assign(new Error(meta.error.message), meta.error) : undefined;
    return { status: meta.status, stdout: readFileSync(stdoutPath), stderr: readFileSync(stderrPath), signal: meta.signal, error };
  } finally {
    rmSync(captureRoot, { recursive: true, force: true });
  }
}

/** 🔍️Budgeted capability probe with captured stdout/stderr — for `--version` checks that must not inherit stdio. */
export function runProbe(cmd: string, args: string[], opts: RunCmdOpts = {}): RunProbeResult {
  const budgetMs = opts.budgetMs ?? defaultBudgetMs(cmd);
  const result = spawnCapturedSync(cmd, args, {
    cwd: opts.cwd,
    env: opts.env ?? process.env,
    timeout: budgetMs,
    killSignal: "SIGKILL",
  });
  if (result.error) {
    if ((result.error as NodeJS.ErrnoException).code === "ETIMEDOUT") {
      console.error(`[budget] ${cmd} ${args.join(" ")} exceeded ${budgetMs}ms — killed. ${budgetTimeoutHint(cmd, opts.onTimeoutHint)}`);
    }
    throw result.error;
  }
  return {
    status: result.status,
    stdout: result.stdout.toString("utf8"),
    stderr: result.stderr.toString("utf8"),
    signal: result.signal,
  };
}

/** 🦀️ One explicit Cargo package/target and nonempty exact law selection. */
/** 🦀️ Composes exact native execution with the repository's admitted manifest and compiler storage policy. */
export async function runRepositoryExactCargoLaws(options: Omit<ExactCargoLawOptions, "manifestPaths" | "cargoTargetDir"> & { manifestPath?: string }, port?: ExactCargoLawPort): Promise<readonly ExactCargoLawReceipt[]> {
  const root = getWorkspaceRoot(), environment = options.env ?? process.env;
  const artifactDirectory = options.artifactDir ?? environment.SEMIO_TEST_ARTIFACT_DIR;
  if (!artifactDirectory || !isAbsolute(artifactDirectory) || !isGeneratedPath(artifactDirectory)) throw new Error("Repository exact Cargo laws require generated artifact storage");
  const manifestPaths = Object.fromEntries(options.groups.map(group => [group.package, options.manifestPath ?? join(root, cargoRepositoryPackage(root, group.package).manifest)]));
  const preparedPort: ExactCargoLawPort = port ?? {
    fingerprint: exactExecutableFingerprint,
    probe: async (command, args, capture) => {
      if (command === "cargo") prepareCargoWorkspaceInvocation(root, args, capture.cwd);
      return await captureOwnedProcess(command, args, capture);
    },
  };
  return await runExactCargoLaws({ ...options, manifestPaths, cargoTargetDir: cargoTargetDirectory(root, environment) }, preparedPort);
}

export interface SpawnDaemonHandle {
  child: ChildProcess;
  kill: () => void;
}

/** 🌙️Spawns a long-lived daemon under [[daemonBudgetMs]]; [[SpawnDaemonHandle.kill]] tears down the whole process tree. */
export function spawnDaemon(cmd: string, args: string[], opts: { cwd?: string; env?: NodeJS.ProcessEnv; stdio?: "inherit" | "pipe" | "ignore" } = {}): SpawnDaemonHandle {
  const child = spawn(cmd, args, {
    cwd: opts.cwd,
    env: opts.env ?? process.env,
    stdio: opts.stdio ?? "inherit",
    detached: process.platform !== "win32",
  });
  let killed = false;
  const budgetMs = daemonBudgetMs();
  const timer = budgetMs > 0 ? setTimeout(() => {
    killed = true;
    if (child.pid) killBudgetTree(child.pid);
  }, budgetMs) : undefined;
  const kill = () => {
    if (timer !== undefined) clearTimeout(timer);
    if (!killed && child.pid) killBudgetTree(child.pid);
  };
  child.on("exit", () => { if (timer !== undefined) clearTimeout(timer); });
  return { child, kill };
}

/** ⏳️Polls `url` with `fetch` every 500ms until it responds `ok`, throwing once `timeoutMs` elapses —
 * the shared readiness gate every `spawnDaemon`-fronted dev/static server (Storybook's own Playwright
 * pipeline, the demonstrator's) waits on before handing off to Playwright. */
export async function waitForHttpUrl(url: string, timeoutMs: number): Promise<void> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const response = await fetch(url);
      if (response.ok) return;
    } catch {
      /* retry */
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`Timed out waiting for ${url}`);
}
//#endregion ⏱️Budget

//#region 📊️Coverage
/** 📊️Whether instrumented coverage collection is on — auto-set by [[resolveTestLevel]] at the `exhaustive` level; `SEMIO_COVERAGE=0` opts out. */
export function coverageEnabled(): boolean {
  return process.env.SEMIO_COVERAGE === "1";
}

export type CoverageKind = "js" | "rust" | "go" | "py" | "dotnet";

/** 📊️Per-toolchain lcov output directory under `.🧬semio/🦑️repo/📊️metrics/coverage`, created on demand. */
export function coverageDir(repoRoot: string, kind: CoverageKind): string {
  const dir = join(getRepoMetaDir(repoRoot), "📊️metrics", "coverage", kind);
  mkdirSync(dir, { recursive: true });
  return dir;
}

/** 📊️Filesystem-safe unique slug for a project's coverage output filename (mirrors the path-slugging idiom used for nx cache keys). */
export function coverageSlug(bundleRoot: string): string {
  return bundleRoot.replace(/[^a-zA-Z0-9_-]+/g, "_");
}

/**
 * 📊️Central, authoritative exclusion list applied at repo-wide aggregation — generated code, vendored/emitted
 * assets, and paths that are GPU-only or Electron-shell and thus unmeasurable by a headless line-coverage
 * runner. Per-tool excludes (vitest `coverage.exclude`, coverage.py `omit`, …) may mirror this for speed, but
 * this list is what decides what counts toward the repo-wide percentage. Every entry has a reason in
 * [[COVERAGE_EXCLUDE_REASONS]] so exclusions stay auditable rather than a silent denominator shrink.
 */
export const COVERAGE_EXCLUDE_GLOBS: readonly string[] = [
  "**/generated/**",
  "framework/module/asset/metabolism/icon/generated/**",
  "**/pkg/**",
  ".storybook/**",
  "**/*.stories.*",
  "**/*.spec.ts",
  "**/*.test.ts",
  "**/*.tex",
  "**/*.wgsl",
  "**/*.svg",
  "elements/client/lib/geometry/topologic/**",
  "framework/product/os/module/renderer/wgpu/**",
  "framework/module/ui/wgpu/**",
  "**/dist/**",
  "**/node_modules/**",
  "**/target/**",
];

/** 📊️One-line rationale per [[COVERAGE_EXCLUDE_GLOBS]] entry — printed alongside the coverage summary. */
export const COVERAGE_EXCLUDE_REASONS: Readonly<Record<string, string>> = {
  "**/generated/**": "Emitted lookup tables/codegen output, not hand-authored logic.",
  "framework/module/asset/metabolism/icon/generated/**": "~22k LOC generated icon table.",
  "**/pkg/**": "wasm-bindgen build output.",
  ".storybook/**": "Covered by Playwright specs, not unit line coverage.",
  "**/*.stories.*": "Storybook fixtures, exercised visually not via line coverage.",
  "**/*.spec.ts": "Playwright specs — browser-process coverage is a separate mechanism.",
  "**/*.test.ts": "Standalone test files measure themselves, not the source under test.",
  "**/*.tex": "LaTeX templates — not executable.",
  "**/*.wgsl": "GPU shader source — not measurable by CPU line coverage.",
  "**/*.svg": "Vector assets — not executable.",
  "elements/client/lib/geometry/topologic/**": "Vendored third-party C++.",
  "framework/product/os/module/renderer/wgpu/**": "GPU rendering internals — smoke-testable only; a headless-GPU harness is out of scope here.",
  "framework/module/ui/wgpu/**": "GPU rendering internals — smoke-testable only; a headless-GPU harness is out of scope here.",
  "**/dist/**": "Build output.",
  "**/node_modules/**": "Third-party dependency code.",
  "**/target/**": "Cargo build output.",
};

function coverageGlobToRegExp(glob: string): RegExp {
  const escaped = glob
    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
    .replace(/\*\*/g, "\x00")
    .replace(/\*/g, "[^/]*")
    .replace(/\x00/g, ".*");
  return new RegExp(`^${escaped}$`);
}

/** 📊️Whether a repo-relative path (forward-slash, no leading `./`) matches any [[COVERAGE_EXCLUDE_GLOBS]] entry. */
export function isCoverageExcluded(relPath: string): boolean {
  const normalized = relPath.replace(/\\/g, "/").replace(/^\.\//, "");
  return COVERAGE_EXCLUDE_GLOBS.some((glob) => coverageGlobToRegExp(glob).test(normalized));
}

/** 📊️`go test` coverage args, appended alongside `goLevelTestArgs` when [[coverageEnabled]]; the text profile is converted to LCOV via [[goProfileToLcov]] at aggregation. */
export function goCoverageArgs(repoRoot: string, moduleLabel: string): string[] {
  if (!coverageEnabled()) return [];
  const file = join(coverageDir(repoRoot, "go"), `${coverageSlug(moduleLabel)}.cover`);
  return ["-covermode=atomic", "-coverpkg=./...", `-coverprofile=${file}`];
}

/** 📊️pytest coverage args, appended alongside `pytestLevelArgs` when [[coverageEnabled]]; `pytest-cov`'s `lcov` reporter writes LCOV directly, no conversion needed. */
export function pytestCoverageArgs(repoRoot: string, moduleLabel: string): string[] {
  if (!coverageEnabled()) return [];
  const file = join(coverageDir(repoRoot, "py"), `${coverageSlug(moduleLabel)}.lcov`);
  return ["--cov", `--cov-report=lcov:${file}`];
}

/** 📊️dotnet test coverage args (coverlet via `--collect`), appended when [[coverageEnabled]]; each project gets its own results-directory subfolder so concurrent projects don't clobber one another's report file. */
export function dotnetCoverageArgs(repoRoot: string, moduleLabel: string): string[] {
  if (!coverageEnabled()) return [];
  const dir = join(coverageDir(repoRoot, "dotnet"), coverageSlug(moduleLabel));
  mkdirSync(dir, { recursive: true });
  return ["--collect", "XPlat Code Coverage;Format=lcov", "--results-directory", dir];
}

//#region 🗄️Lcov
export type LcovFileRecord = { path: string; lines: Map<number, number> };

/** 📊️Parses one LCOV text blob into per-file line-hit maps (only `SF:`/`DA:`/`end_of_record` — the subset every toolchain here emits). */
export function parseLcov(text: string): LcovFileRecord[] {
  const records: LcovFileRecord[] = [];
  let current: LcovFileRecord | undefined;
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (line.startsWith("SF:")) {
      current = { path: line.slice(3), lines: new Map() };
      records.push(current);
    } else if (line.startsWith("DA:") && current) {
      const [lineNoStr, hitsStr] = line.slice(3).split(",");
      const lineNo = Number(lineNoStr);
      const hits = Number(hitsStr);
      current.lines.set(lineNo, (current.lines.get(lineNo) ?? 0) + hits);
    } else if (line === "end_of_record") {
      current = undefined;
    }
  }
  return records;
}

/** 📊️Merges LCOV records from multiple toolchain runs — line-hit counts sum, covered line numbers union. */
export function mergeLcov(recordSets: LcovFileRecord[][]): Map<string, Map<number, number>> {
  const merged = new Map<string, Map<number, number>>();
  for (const records of recordSets) {
    for (const record of records) {
      const target = merged.get(record.path) ?? new Map<number, number>();
      for (const [lineNo, hits] of record.lines) target.set(lineNo, (target.get(lineNo) ?? 0) + hits);
      merged.set(record.path, target);
    }
  }
  return merged;
}

/** 📊️Renders a merged coverage map back to LCOV text (one `SF:`/`DA:`×N/`end_of_record` block per file, lines sorted ascending). */
export function renderLcov(merged: Map<string, Map<number, number>>): string {
  const chunks: string[] = [];
  for (const [path, lines] of merged) {
    chunks.push(`SF:${path}`);
    for (const lineNo of [...lines.keys()].sort((a, b) => a - b)) chunks.push(`DA:${lineNo},${lines.get(lineNo)}`);
    chunks.push("end_of_record", "");
  }
  return chunks.join("\n");
}

/** 📊️Expands a `go test -coverprofile` text block (`mode: <mode>` header, then `file:startLine.startCol,endLine.endCol numStmt count` records) into per-line LCOV records — every line in a statement's range is marked hit iff `count > 0`. */
export function goProfileToLcov(text: string): LcovFileRecord[] {
  const byFile = new Map<string, Map<number, number>>();
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("mode:")) continue;
    const match = /^(.+):(\d+)\.\d+,(\d+)\.\d+ \d+ (\d+)$/.exec(line);
    if (!match) continue;
    const [, file, startStr, endStr, countStr] = match;
    const start = Number(startStr);
    const end = Number(endStr);
    const hits = Number(countStr);
    const lines = byFile.get(file) ?? new Map<number, number>();
    for (let lineNo = start; lineNo <= end; lineNo++) lines.set(lineNo, (lines.get(lineNo) ?? 0) + hits);
    byFile.set(file, lines);
  }
  return [...byFile.entries()].map(([path, lines]) => ({ path, lines }));
}

export type CoverageSummary = {
  linesFound: number;
  linesHit: number;
  pct: number;
  perFile: { path: string; linesFound: number; linesHit: number; pct: number }[];
};

/** 📊️Reduces a merged coverage map to a repo-wide percentage plus a worst-offenders table, after dropping [[isCoverageExcluded]] paths. */
export function summarizeCoverage(merged: Map<string, Map<number, number>>): CoverageSummary {
  let linesFound = 0;
  let linesHit = 0;
  const perFile: CoverageSummary["perFile"] = [];
  for (const [path, lines] of merged) {
    if (isCoverageExcluded(path)) continue;
    const found = lines.size;
    const hit = [...lines.values()].filter((count) => count > 0).length;
    linesFound += found;
    linesHit += hit;
    perFile.push({ path, linesFound: found, linesHit: hit, pct: found === 0 ? 100 : (hit / found) * 100 });
  }
  perFile.sort((a, b) => a.pct - b.pct || b.linesFound - a.linesFound);
  return { linesFound, linesHit, pct: linesFound === 0 ? 0 : (linesHit / linesFound) * 100, perFile };
}

/** 📊️Prints the worst-covered files and hard-fails (`process.exit(1)`) below `thresholdPct`. */
export function enforceCoverageThreshold(summary: CoverageSummary, thresholdPct: number, worstCount = 25): void {
  console.log(`[coverage] ${summary.linesHit}/${summary.linesFound} lines (${summary.pct.toFixed(2)}%), threshold ${thresholdPct}%.`);
  if (summary.pct < thresholdPct) {
    console.log(`[coverage] worst ${Math.min(worstCount, summary.perFile.length)} files:`);
    for (const file of summary.perFile.slice(0, worstCount)) {
      console.log(`  ${file.pct.toFixed(1)}% (${file.linesHit}/${file.linesFound})  ${file.path}`);
    }
    console.error(`[coverage] ${summary.pct.toFixed(2)}% < ${thresholdPct}% — exhaustive gate failed.`);
    process.exit(1);
  }
}
//#endregion 🗄️Lcov
//#endregion 📊️Coverage

//#region 🧹️CargoLint
/**
 * 🧹️Zero-warning gate for a crate: `cargo clippy -p <pkg> --all-targets -- -D warnings`.
 * Deny-on-warnings lives ONLY in this trailing clippy arg — never in RUSTFLAGS, which
 * would replace (not merge with) `.cargo/config.toml`'s rustflags (`-Z threads=8`, the
 * wasm32 `getrandom_backend` cfg, mold) and break every wasm build. See
 * `[workspace.lints]` in the root `Cargo.toml` for the shared lint baseline this checks.
 */
export function runCargoLint(packages: string[], cwd: string, extraArgs: string[] = [], env: NodeJS.ProcessEnv = process.env): void {
  const resolvedPackages = resolveCargoPackageNames(packages, cwd);
  const repository = getWorkspaceRoot(), rows = resolvedPackages.map(name => cargoRepositoryPackage(repository, name));
  const scopes = [...new Set(rows.map(row => row.workspace))];
  if (scopes.length > 1) { for (const scope of scopes) runCargoLint(rows.filter(row => row.workspace === scope).map(row => row.name), cwd, extraArgs, env); return; }
  const packageArgs = [...(rows.length ? ["--manifest-path", join(repository, rows[0]!.manifest)] : []), ...resolvedPackages.flatMap((pkg) => ["-p", pkg])];
  runCmd("cargo", ["clippy", ...packageArgs, "--all-targets", ...extraArgs, "--", "-D", "warnings"], { cwd, env, budgetMs: buildBudgetMs() });
}
//#endregion 🧹️CargoLint


//#region ⚙️ViteConfigLoader
/**
 * ⚙️ Pick Vite's config loader for the current runtime.
 * Node 24+ defaults Vite to `native` strip-only TypeScript, which rejects constructor parameter
 * properties used across monorepo configs — so Node must use `bundle`. Bun already runs full
 * TypeScript, and Vite's `bundle` loader fails on this config with an opaque `undefined` error,
 * so Bun keeps `native`. Callers that already pass `--configLoader` win.
 * @see https://vite.dev/config/#config-loader
 */
export function viteConfigLoader(): "native" | "bundle" {
  return typeof (globalThis as { Bun?: unknown }).Bun === "object" ? "native" : "bundle";
}

/** 🧷️ Prepends {@link viteConfigLoader}'s choice to a Vite CLI argument list. */
export function withViteConfigLoader(args: readonly string[]): string[] {
  if (args.includes("--configLoader")) return [...args];
  const loader = viteConfigLoader();
  const out = [...args];
  const viteIdx = out.indexOf("vite");
  if (viteIdx >= 0) {
    out.splice(viteIdx + 1, 0, "--configLoader", loader);
    return out;
  }
  return ["--configLoader", loader, ...out];
}

function bunArgsForVite(args: readonly string[]): string[] {
  return args.includes("vite") ? withViteConfigLoader(args) : [...args];
}
//#endregion ⚙️ViteConfigLoader

/** 🧭️ The workspace's own Vite CLI entry (`vite/bin/vite.js`), resolved through the package instead of `node_modules/.bin`,
 * whose extensionless `vite` is a POSIX shell shim on Windows whenever another package manager wrote it. */
function viteCliEntry(cwd: string): string {
  return join(dirname(createRequire(join(findWorkspaceRoot(cwd), "package.json")).resolve("vite/package.json")), "bin/vite.js");
}

function bunxCmdArgs(args: readonly string[], cwd: string): string[] {
  const formatted = bunArgsForVite(args);
  const viteIdx = formatted.indexOf("vite");
  if (viteIdx >= 0) {
    const copy = [...formatted];
    copy[viteIdx] = viteCliEntry(cwd);
    return copy;
  }
  const binName = formatted[0];
  if (binName && binName !== "x") {
    const resolved = resolveWorkspaceBin(binName, cwd);
    if (resolved) {
      return [resolved, ...formatted.slice(1)];
    }
  }
  return ["x", ...formatted];
}

/** 🥖️Runs `bun` with inherited stdio in `cwd`. */
export function runBun(args: string[], cwd: string, env: NodeJS.ProcessEnv = process.env): void {
  runCmd(process.execPath, bunArgsForVite(args), { cwd, env });
}

/** 🥖️Runs `bunx` synchronously in `cwd`, returning status code. */
export function runBunxStatus(args: string[], cwd: string, env: NodeJS.ProcessEnv = process.env): number {
  const result = spawnSync(process.execPath, bunxCmdArgs(args, cwd), { cwd, env, shell: false, stdio: "inherit" });
  if (result.error) {
    console.error(result.error);
    return 1;
  }
  return result.status ?? 1;
}

/** 🥖️Runs `bunx` synchronously in `cwd`. */
export function runBunx(args: string[], cwd: string, env: NodeJS.ProcessEnv = process.env): void {
  const status = runBunxStatus(args, cwd, env);
  if (status !== 0) process.exit(status);
}

/** 🥖️Spawns `bunx` asynchronously; exits with child code. */
export function spawnBunx(args: string[], cwd: string, env: NodeJS.ProcessEnv = process.env): Promise<void> {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, bunxCmdArgs(args, cwd), { cwd, env, shell: false, stdio: "inherit" });
    child.on("exit", (code) => {
      if ((code ?? 0) === 0) resolve();
      else process.exit(code ?? 0);
    });
    child.on("error", (error) => {
      console.error(error);
      reject(error);
      process.exit(1);
    });
  });
}

/** 🥖️Spawns `bun` asynchronously; exits with child code. */
export function spawnBun(args: string[], cwd: string, env: NodeJS.ProcessEnv = process.env): void {
  const child = spawn(process.execPath, bunArgsForVite(args), { cwd, env, shell: false, stdio: "inherit", windowsHide: true });
  child.on("exit", (code) => process.exit(code ?? 0));
  child.on("error", (error) => {
    console.error(error);
    process.exit(1);
  });
}

/** ▶️Vite dev server with polling-friendly env defaults. */
export function runViteDev(bundleRoot: string, segments: string[], opts: { config: string; portEnv?: string; defaultPort?: string }): void {
  const env = playPollingEnv();
  const host = process.env.DEVCONTAINER === "true" ? "0.0.0.0" : "127.0.0.1";
  const port = process.env[opts.portEnv ?? "VITE_PORT"] ?? opts.defaultPort ?? "5173";
  spawnBun(["run", "vite", "--config", opts.config, "--host", host, "--port", port, ...segments], bundleRoot, env);
}

/** ▶️Vite production build. */
export function runViteBuild(bundleRoot: string, segments: string[], config: string): void {
  runCmd(process.execPath, [viteCliEntry(bundleRoot), "build", "--config", config, "--configLoader", "bundle", ...segments], { cwd: bundleRoot, env: devToolingEnv() });
}

/**
 * ▶️Vitest run in bundle directory, under the [[runRepositoryTestCommand]] wall-clock budget. Appends v8 lcov coverage
 * flags when [[coverageEnabled]]. Invokes the workspace's own `node_modules/vitest/vitest.mjs` directly rather
 * than `bun x vitest` — `bunx` resolves its own globally cached vitest version, which can silently drift from
 * the workspace's pinned version (observed: a cached 3.x core paired with a locally installed 4.x
 * `@vitest/coverage-v8` crashes the coverage provider on an undefined `reportsDirectory`). Coverage runs use
 * plain `node`, not bun, as the runtime — `@vitest/coverage-v8` drives V8 coverage via `node:inspector`'s
 * `Profiler.startPreciseCoverage`, which Bun's `node:inspector` shim doesn't implement (observed: "Coverage
 * APIs are not supported"); non-coverage runs keep using bun for its faster startup.
 */
/** 🧪️ Builds Vitest argv without overriding the owning config's no-test policy.
 *
 * 🩸️ `--config` is passed ABSOLUTE. Every call site writes the path relative to its own bundle root
 * (the shape `runVitestConfigArgumentTokens` scans for), but vitest 4 resolves a relative `--config`
 * against the root it detects — this repo's own root — not the working directory it was launched in.
 * `@semio-tech/framework:test` was the caught case: its `../../🧪️tests/🎚️config/🟦️.ts` resolved to
 * `<repo parent>/🧪️tests/🎚️config/🟦️.ts`, esbuild could not load it, and the run reported
 * "No test files found, exiting with code 1" — with the config silently absent, so its `includeSource`
 * never collected the kernel's in-source suites. Resolving here keeps the relative literals at the call
 * sites and makes the launched cwd authoritative again. */
/** 📋️ Supplies actual Repo storage policy to an explicitly selected executable owner. */
export function repositoryProcessOwnerContextV1(cwd:string):ProcessOwnerContextV1{
  const repository=findWorkspaceRoot(cwd);
  return {version:1,cwd:resolve(cwd),cacheRoot:repoCacheDirectory(repository),leaseDirectory:repoCacheDirectory(repository,"agents","resource-leases")};
}

export function repositoryVitestPolicyV1(bundleRoot:string,env:Readonly<Record<string,string|undefined>>=process.env):VitestPolicyV1{
  const repository=findWorkspaceRoot(bundleRoot);
  return {version:1,cwd:resolve(bundleRoot),toolPath:join(repository,"node_modules","vitest","vitest.mjs"),runtime:"node",coverageRuntime:"node",cacheRoot:repoCacheDirectory(repository,"vite"),coverageDirectory:join(coverageDir(repository,"js"),coverageSlug(bundleRoot)),budgetMs:Number(env.SEMIO_TEST_BUDGET_MS??TEST_LEVEL_BUDGET_MS[isTestLevel(env.SEMIO_TEST_LEVEL)?env.SEMIO_TEST_LEVEL:"fundamental"])};
}

export function vitestRunArguments(bundleRoot: string, segments: string[], config: string, collectingCoverage = coverageEnabled()): string[] {
  return vitestArgumentsV1(repositoryVitestPolicyV1(bundleRoot),segments,config,collectingCoverage);
}

export async function runVitest(bundleRoot: string, segments: string[], config: string): Promise<void> {
  const policy=repositoryVitestPolicyV1(bundleRoot),env=devToolingEnv({SEMIO_VITEST_POLICY:JSON.stringify(policy)});
  await runVitestV1(policy,segments,config,env);
}

export { SEMIO_LOCKED_LOCALE_ENV, SEMIO_LOCKED_TERMINOLOGY_ENV, SEMIO_LOCKED_THEME_ENV, SEMIO_LOCKED_APPEARANCE_ENV, SEMIO_BRAND_ENV, SEMIO_DEFAULT_EXAMPLE_ENV, frameworkOsLockedPrefsEnv } from "./🎮️playground/🔒️preferences/🟦️.ts";

//#region 🖥️FrameworkOsPlaygroundDev
/** 🔌️ Local dev-time asset server port for wgpu Trunk/native playgrounds (Trunk forwards
 * route-scoped requests — e.g. `/osm`, `/vt`, `/dem` — here; driven by each playground's declared
 * `[[package.metadata.semio.assets]]` rows, not any one app's routes). */
export const SEMIO_ASSET_SERVER_PORT = 6141;

/** 🔌️ Process env for the absolute asset server URL base (native-bin wgpu route-relative fetches). */
export const SEMIO_ASSET_BASE_URL_ENV = "SEMIO_ASSET_BASE_URL";

/** 🔌️ Resolves the default dev port for a given catalog variant and renderer. */
export function frameworkOsPlaygroundDefaultPort(catalog: readonly PlaygroundVariant[], variant: string, renderer: string): number {
  const row = catalog.find((r) => r.variant === variant);
  if (!row) return 6066;
  return renderer === "wgpu" ? row.ports.wgpu : row.ports.react;
}

/** 🎯️ Resolves `bun ./📜️script.ts dev …` segments to a framework OS plugin filter via the catalog. */
export function resolveFrameworkOsPlaygroundPlugin(catalog: readonly PlaygroundVariant[], segments: readonly string[]): { readonly plugin: string; readonly rest: readonly string[] } | null {
  if (segments.length === 0) return null;
  for (let len = segments.length; len >= 1; len--) {
    const alias = segments.slice(0, len).join(" ");
    const row = catalog.find((r) => r.variant === alias || r.aliases.includes(alias));
    if (row) {
      return { plugin: row.variant, rest: segments.slice(len) };
    }
  }
  return null;
}

/** 🧊️ Env for `@semio-tech/framework-os-dev:dev` with a plugin filter and the renderer an
 * explicit `SEMIO_RENDERER` (launch row, `extra`) selects — wgpu only as the unset default. The value
 * picks the `dev-<variant>-<renderer>-<profile>` target in `resolveNxInvocation`, so a react launch
 * row reaches Vite and never the wgpu browser server. */
export function frameworkOsPlaygroundDevEnv(catalog: readonly PlaygroundVariant[], plugin: string, extra: Partial<NodeJS.ProcessEnv> = {}, env: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  const renderer = extra.SEMIO_RENDERER ?? env.SEMIO_RENDERER ?? "wgpu";
  const defaultPort = frameworkOsPlaygroundDefaultPort(catalog, plugin, renderer);
  const portVal = extra.S_OS_PORT || env.S_OS_PORT || String(defaultPort);
  return devToolingEnv({
    SEMIO_PLUGIN: plugin,
    ...extra,
    SEMIO_RENDERER: renderer,
    S_OS_PORT: portVal,
  });
}
//#endregion 🖥️FrameworkOsPlaygroundDev

/** 🧰️Play/vite dev env with optional file-watcher polling defaults. Polling only makes sense where
 * native filesystem events don't reach the watcher (bind-mounted devcontainers) — on native macOS/
 * Windows/Linux it just burns CPU/RSS across every spawned dev server for no benefit. An explicit
 * `WATCHPACK_POLLING` always wins as a manual override in either direction. */
export function playPollingEnv(extra: Partial<NodeJS.ProcessEnv> = {}): NodeJS.ProcessEnv {
  const pollingDefault = process.env.WATCHPACK_POLLING !== undefined ? {} : process.env.DEVCONTAINER === "true" ? { WATCHPACK_POLLING: "true", CHOKIDAR_USEPOLLING: "true" } : {};
  return devToolingEnv({
    ...pollingDefault,
    ...extra,
  });
}

/** 🔒️ Parses optional `example <id>` argv prefix for playground play scripts. */
export function consumePlaygroundExampleArgv(segments: string[], resolveExampleId: (slug: string) => string | undefined): { readonly segments: string[]; readonly exampleEnv: NodeJS.ProcessEnv } {
  if (segments[0] !== "example" || !segments[1]) {
    return { segments, exampleEnv: {} };
  }
  const exampleId = resolveExampleId(segments[1]);
  if (!exampleId) {
    console.error(`[play] unknown example ${JSON.stringify(segments[1])}`);
    process.exit(1);
  }
  return {
    segments: segments.slice(2),
    exampleEnv: { PLAYGROUND_LOCKED_EXAMPLE_ID: exampleId },
  };
}

/** ▶️Playwright test run in bundle directory; browsers land in the shared cache root. */
export function runPlaywright(bundleRoot: string, config: string, segments: string[] = []): void {
